messages.content:
{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": [
      {
        "ref": "L01",
        "text": "(未詳/子羽)"
      },
      {
        "ref": "L02",
        "text": "(中丞世語曰㝢少與裴楷王戎杜黙俱有名仕晉至/温顒已見荀氏譜曰㝢字景伯祖式太尉父保御史)"
      },
      {
        "ref": "L03",
        "text": "(書/尚)"
      },
      {
        "ref": "L04",
        "text": "(鹿郡人父放魏驃騎將軍許/晉百官名曰劉許字文生涿)"
      },
      {
        "ref": "L05",
        "text": "(故曰士卿互其辭也宗正卿或曰士卿/恵帝時為宗正卿按許與張華同范陽人)"
      },
      {
        "ref": "L06",
        "text": "(仕至侍中詡字思淵滎陽開封人為衞尉/晉諸公賛曰湛字潤甫新野人以文義達)"
      },
      {
        "ref": "L07",
        "text": "(史父褒司空/卿祖泰揚州刺)"
      },
      {
        "ref": "L08",
        "text": "(意此語則此六句還以目上六人而/文士傳曰華為人少威儀多姿態推)"
      },
      {
        "ref": "L09",
        "text": "(辯麗英博而有此稱未詳/口如含膠飴則指鄒湛湛)"
      },
      {
        "ref": "L10",
        "text": "(友有秦生者雖有姊夫之尊/張敏集載頭責子羽文曰余)"
      },
      {
        "ref": "L11",
        "text": "(㝢范陽張茂先華士卿劉文生許南陽鄒潤甫湛河/少而狎焉同時好暱有太原温長仁顒潁川荀景伯)"
      },
      {
        "ref": "L12",
        "text": "(屢沽而無善價亢志自若終不衰墮為之慨然又怪/南鄭思淵詡數年之中繼踵登朝而此賢身處陋巷)"
      },
      {
        "ref": "L13",
        "text": "(之義故因秦生容貌之盛為頭責之文以戲之并以/諸賢既已在位曽無伐木嚶鳴之聲甚違王貢彈冠)"
      },
      {
        "ref": "L14",
        "text": "(頭責子羽曰吾託子為頭萬有餘日矣大塊禀我以/嘲六子焉雖似諧謔實有興也其文曰維泰始元年)"
      },
      {
        "ref": "L15",
        "text": "(眸子摛光雙顴隆起毎至出入之間遨遊市里行者/精造我以形我為子植髪膚置鼻耳安眉須揷牙齒)"
      },
      {
        "ref": "L16",
        "text": "(﨑嶇如此者故我形之足偉也子冠冕不戴金銀不/辟易坐者竦跽或稱君侯或言將軍捧手傾側佇立)"
      },
      {
        "ref": "L17",
        "text": "(間糞壤汙黒嵗莫年過曽不自悔子厭我於形容我/佩釵以當笄帢以代幗㫖味弗甞食粟茹菜隈摧園)"
      },
      {
        "ref": "L18",
        "text": "(讐我視子如仇居常不樂兩者俱憂何其鄙哉子欲/賤子乎意態若此者乎必子行已之累也子遇我如)"
      },
      {
        "ref": "L19",
        "text": "(見封殖子欲為名高也則當如許由子威卞隨務光/為人寳也則當如臯陶后稷巫咸伊陟保乂王家永)"
      },
      {
        "ref": "L20",
        "text": "(通陸生鄧公轉禍為福令辭從容子欲為進趣也則/洗耳逃禄千嵗流芳子欲為遊說也則當如陳軫蒯)"
      },
      {
        "ref": "L21",
        "text": "(子欲為恬淡也則當如老聃之守一莊周之自逸廓/當如賈生之求試終軍之請使砥礪鋒穎以幹王事)"
      },
      {
        "ref": "L22",
        "text": "(索漁父之瀺灂棲遲神丘垂餌巨壑此一介之所以/然離欲志陵雲日子欲為隱遁也則當如榮期之帶)"
      },
      {
        "ref": "L23",
        "text": "(窮賤守此愚惑察子之情觀子之志退不為於處士/顯身成名者也今子上不希道德中不效儒墨塊然)"
      },
      {
        "ref": "L24",
        "text": "(亦過乎於是子羽愀然深念而對曰凡所教敇謹聞/進無望於三事而徒翫日勞形習為常人之所喜不)"
      },
      {
        "ref": "L25",
        "text": "(欲使吾為忠也即當如伍胥屈平欲使吾為信也則/命矣以受性拘係不閒禮義設以天幸為子所寄今)"
      },
      {
        "ref": "L26",
        "text": "(貞此四者人之所忌故吾不敢造意頭曰子所謂天/當殺身以成名欲使吾為介節邪則當赴水火以全)"
      },
      {
        "ref": "L27",
        "text": "(爾以養性誨爾以優游而以蟣蝨同情不聽我謀悲/刑地網剛德之尤不登山抱木則蹇裳赴流吾欲告)"
      },
      {
        "ref": "L28",
        "text": "(不如太原温顒穎川荀㝢范陽張華士卿劉許南陽/哉俱寓人體而獨為子頭且擬人其倫喻子儕偶子)"
      },
      {
        "ref": "L29",
        "text": "(言語或淹伊多恣態或讙譁少智諝或口如含膠飴/鄒湛河南鄭詡此數子者或謇喫無宫商或尫陋希)"
      },
      {
        "ref": "L30",
        "text": "(並登天府夫䑛痔得車沈淵得珠豈若夫子徒令脣/或頭如巾韲杵而猶文采可觀意思詳序攀龍附鳯)"
      },
      {
        "ref": "L31",
        "text": "(鑿池抱罋難以求富嗟乎子羽何異檻中之熊深穽/舌腐爛手足沾濡哉居有事之世而耻為權圖譬猶)"
      },
      {
        "ref": "L32",
        "text": "(拳局剪蹙至老無所希也支離其形猶能不困非命/之虎石間饑蟹竇中之鼠事力雖勤見功甚苦宜其)"
      },
      {
        "ref": "L33",
        "text": "(子同處也/也夫豈與夫)"
      }
    ]
  },
  "frozen_questions": [
    {
      "gap": "缺少“頭”指代何物以及它责备秦子羽的具体叙事框架，读者无法理解责备的缘由和场景",
      "question_id": "Q1",
      "story_span": "頭責秦子羽云子曽不如太原温顒潁川荀㝢"
    },
    {
      "gap": "缺少“士卿”的指认，无法确定是官职还是人名，从而影响对刘许身份及所列人数的理解",
      "question_id": "Q2",
      "story_span": "范陽張華士卿劉許"
    },
    {
      "gap": "缺少对“天府”实际所指的说明，它决定“攀龙附凤”的隐喻方向，影响对整则故事讽刺意图的判断",
      "question_id": "Q3",
      "story_span": "而猶以文采可觀意思詳\n序攀龍附鳯並登天府"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": [
      {
        "layer": "collation_note",
        "ref": "J01",
        "source_labels": [],
        "speaker": null,
        "text": "「謇喫」「喫」，景宋本及沈本作「吃」。注「許由子威」「威」，沈本作「臧」。注「廓然離欲」「欲」，沈本作「俗」。注「不聞禮義」「聞」，景宋本及沈本俱作「閑」。注「為忠也」「為信也」「也」，沈本俱作「邪」。注「而以蟣蝨同情」「以」，沈本作「與」。注「而猶文采可觀」「猶」下沈本有「以」字。注「剪蹙」「剪」，景宋本及沈本俱作「煎」。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J02",
        "source_labels": [
          "三國志",
          "世語",
          "家傳"
        ],
        "speaker": "程炎震",
        "text": "〔一〕 李慈銘云：「案『式』當作『彧』、『保』當作『俁』。三國志荀彧傳『子俁御史中丞』，注引荀氏家傳曰『俁字叔倩，子宇，字景伯』，又引世語云云，與此同。」程炎震云：「『祖式、父保』，當據魏志十荀彧傳改作『祖彧、父俁』。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J03",
        "source_labels": [],
        "speaker": "程炎震",
        "text": "〔二〕 魏志劉放傳曰：「放薨，子正嗣。」注云：「臣松之案：頭責子羽曰『士卿劉許』，字文生，正之弟也。與張華六人，並稱文辭可觀，意思詳序。晉惠帝世，許為越騎校尉。」隋志云：「梁有宗正劉訏集二卷，錄一卷亡。」新唐志作劉許。程炎震云：「魏書劉放傳『子正』，裴注曰：『頭責子羽文曰「士卿劉許」，字文生，正之弟也。與張華六人並稱，文辭可觀，意思詳序。』」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J04",
        "source_labels": [
          "晉書"
        ],
        "speaker": null,
        "text": "〔三〕 晉書地理志：武帝平吳，分南陽立義陽郡。張敏此文作於泰始元年，在未平吳之前。故注引此文，兩稱南陽鄒湛。此作義陽者，蓋後來所改。然惠帝時分南陽立新野郡，而此不稱新野，則臨川所據者晉初之本也。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J05",
        "source_labels": [
          "晉書"
        ],
        "speaker": "李慈銘",
        "text": "〔四〕 李慈銘云：「案『褒』當作『袤』。晉書鄭袤傳：『袤字林叔，滎陽開封人，漢大司農眾之元孫。』父即范書所言公業也。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J06",
        "source_labels": [],
        "speaker": null,
        "text": "〔五〕 通雅卷五曰：「●●，一作謇喫。列子曰：●●凌誶，好陵責罵人也。●，吃也。說文曰：急性也。方言：●●，吃也。或謂之軋，謂之●。郭璞曰：江東曰●，皆謂口吃好言之狀。頭責子羽文『或謇喫無宮商』。喫，廣韻音毄。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J07",
        "source_labels": [],
        "speaker": "余嘉錫",
        "text": "〔六〕 嘉錫案：言其頭小而銳，如搗兗之杵，而冠之以巾也。初學記十九引劉思真醜婦賦云「頭似研米槌」。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J08",
        "source_labels": [
          "晉書"
        ],
        "speaker": "余嘉錫",
        "text": "〔七〕 隋志有晉尚書郎張敏集二卷，梁五卷。唐宋志仍二卷。洪邁容齋五筆四曰：「故簏中得舊書一帙，題為晉代名臣文集，凡十有四家。所載多不能全。有張敏者，太原人，仕歷平南參軍、太子舍人、濟北長史。其一篇曰頭責子羽文，極為尖新。古來文士，皆無此作。恐藝文類聚、文苑英華或有之。惜其泯沒不傳，謾采之以遺博雅君子。其文九百餘言，頗有東方朔客難，劉孝標絕交論之體，集仙傳所載神女成公智瓊傳見於太平廣記，蓋敏之作也。」嚴可均全晉文八十曰：「張敏太原中都人，咸寧中為尚書郎，領祕書監，太康初出為益州刺史。」文廷式補晉書藝文志丁部六曰：「張敏集，遂初堂書目尚著錄。是此書南宋猶存。」嘉錫案：張敏仕履，得洪氏、嚴氏所述而始全。然洪氏未考世說，故不知頭責子羽文具存孝標注中。且云文苑英華或有之。夫英華上繼文選，起自梁代，安得有晉人文耶？嚴氏又…"
      },
      {
        "layer": "jianshu_note",
        "ref": "J09",
        "source_labels": [],
        "speaker": "李慈銘",
        "text": "〔八〕 李慈銘云：「案洪氏邁容齋五筆引此文小有異同。其此本灼然誤者，輒注其旁。可互通者別出之。『狎焉』作『狎之』，『好暱』作『暱好』。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J10",
        "source_labels": [
          "漢書"
        ],
        "speaker": null,
        "text": "〔九〕 漢書東方朔傳：「上復問朔：『方今公孫丞相、兒大夫、董仲舒之倫，先生自視何與比哉？』朔對曰：『臣觀其臿齒牙，樹頰頦，吐脣吻，擢項頤，結股腳，連脽尻，遺蛇其跡，行步偊旅，臣朔雖不肖，尚兼此數子者。』」張敏所謂植髮膚云云，其意度蓋出於此。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J11",
        "source_labels": [],
        "speaker": "李慈銘",
        "text": "〔一０〕 李慈銘云：洪本「兩『不』字俱作『弗』。『帢』作『幍』，乃『』之誤，『』即『帢』字。『幗』作『帶』，當以洪本為是，帶與戴佩韻。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J12",
        "source_labels": [
          "漢書"
        ],
        "speaker": null,
        "text": "〔一一〕 漢書匈奴傳曰：「高后時，冒頓寖驕，迺為書使使遺高后曰：『陛下獨立，孤僨獨居。兩者不樂，無以自虞。』」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J13",
        "source_labels": [],
        "speaker": "李慈銘",
        "text": "〔一二〕 李慈銘云：「『人寶』洪本作『仁賢』，誤。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J14",
        "source_labels": [
          "漢書"
        ],
        "speaker": null,
        "text": "〔一三〕 漢書晁錯傳曰：「錯已死，謁者僕射鄧公為校尉，擊吳楚為將，還見上，上問曰：『道軍所來，聞晁錯死，吳楚罷不？』鄧公曰：『吳為反數十歲矣。發怒削地，誅錯為名，其意不在錯也。且臣恐天下之士，拑口不敢復言矣。』上曰：『何哉？』鄧公曰：『夫晁錯患諸侯彊大不可制，故請削之，尊京師。萬世之利也。計畫始行，卒受大戮，內杜忠臣之口，外為諸侯報仇。臣竊為陛下不取也。』於是景帝喟然長息曰：『公言善，吾亦恨之。』迺拜鄧公為城陽中尉。鄧公，成固人也。多奇計。建元年中上招賢良，公卿言鄧先。鄧先時免，起家為九卿，一年，復謝病，免歸。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J15",
        "source_labels": [],
        "speaker": "李慈銘",
        "text": "〔一四〕 李慈銘云：「洪本令作含，疑此誤。」（以下「李云」並據洪邁容齋五筆校。）"
      },
      {
        "layer": "jianshu_note",
        "ref": "J16",
        "source_labels": [],
        "speaker": null,
        "text": "〔一五〕 李云：「廓作漠，欲作俗。六『也』字俱作『耶』，古也耶通用，也自為古。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J17",
        "source_labels": [],
        "speaker": null,
        "text": "〔一六〕 李云：「一介之下有人字，此脫。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J18",
        "source_labels": [],
        "speaker": null,
        "text": "〔一七〕 李云：「受上無以字，此誤衍。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J19",
        "source_labels": [],
        "speaker": null,
        "text": "〔一八〕 李云：「設作誤。三『也』字亦皆作耶，伍作包。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J20",
        "source_labels": [],
        "speaker": null,
        "text": "〔一九〕 李云：「以作與。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J21",
        "source_labels": [],
        "speaker": null,
        "text": "〔二０〕 李云：「子不如作曾不如。案當作子曾不如。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J22",
        "source_labels": [],
        "speaker": "程炎震",
        "text": "〔二一〕 程炎震云：「文心雕龍諧隱篇作握舂杵。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J23",
        "source_labels": [],
        "speaker": null,
        "text": "〔二二〕 李云：「猶下有以字，與正文合。得珠作竊珠。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J24",
        "source_labels": [],
        "speaker": null,
        "text": "〔二三〕 李云：「檻中作牢檻。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J25",
        "source_labels": [],
        "speaker": null,
        "text": "〔二四〕 李云：「剪作煎。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J26",
        "source_labels": [],
        "speaker": null,
        "text": "〔二五〕 李云：「洪本作命也夫與子同處。」"
      }
    ]
  },
  "primary_text": {
    "label": "世說新語正文",
